    elif ch == ')':
        processed.append(' ) ')
    else:
        processed.append(ch)

tokens = ''.join(processed).split()
insideParentheses = False
maxLength = 0
parenthesesCount = 0

for token in tokens:
    if '(' in token:
        insideParentheses = True
    elif ')' in token:
        insideParentheses = False
    elif '(' not in token and ')' not in token:
        if insideParentheses:
            parenthesesCount += 1
        else:
            maxLength = max(maxLength, len(token))

print(f"{maxLength} {parenthesesCount}")

